import{_ as a,o as e,c as o,l as s,t as i,N as n}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"git-mktag | x-cmd man (git man1) | Creates a tag object with extra validation","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-mktag - Creates a tag object with extra validation","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-mktag | x-cmd man (git man1) | Creates a tag object with extra validation"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-mktag - Creates a tag object with extra validation"}]]},"headers":[],"params":{"isMan":true,"man":"git-mktag","category":"git man1","desc":"Creates a tag object with extra validation"},"relativePath":"git/man1/git-mktag.md","filePath":"git/man1/git-mktag.md"}'),r={name:"git/man1/git-mktag.md"},g={class:"visually-hidden"},l=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-mktag - Creates a tag object with extra validation</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mktag</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Reads a tag contents on standard input and creates a tag object. The output is the new tag&#39;s &lt;object&gt; identifier.</p><p>This command is mostly equivalent to <strong>git-hash-object</strong>(1) invoked with <strong>-t tag -w --stdin</strong>. I.e. both of these will create and write a tag found in <strong>my-tag</strong>:</p><blockquote><pre><code>git mktag &lt;my-tag
git hash-object -t tag -w --stdin &lt;my-tag
</code></pre></blockquote><p>The difference is that mktag will die before writing the tag if the tag doesn&#39;t pass a <strong>git-fsck</strong>(1) check.</p><p>The &quot;fsck&quot; check done mktag is stricter than what <strong>git-fsck</strong>(1) would run by default in that all <strong>fsck.&lt;msg-id&gt;</strong> messages are promoted from warnings to errors (so e.g. a missing &quot;tagger&quot; line is an error).</p><p>Extra headers in the object are also an error under mktag, but ignored by <strong>git-fsck</strong>(1). This extra check can be turned off by setting the appropriate <strong>fsck.&lt;msg-id&gt;</strong> varible:</p><blockquote><pre><code>git -c fsck.extraHeaderEntry=ignore mktag &lt;my-tag-with-headers
</code></pre></blockquote><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--strict</p><blockquote><p>By default mktag turns on the equivalent of <strong>git-fsck</strong>(1) <strong>--strict</strong> mode. Use <strong>--no-strict</strong> to disable it.</p></blockquote><h2 id="tag-format" tabindex="-1">TAG FORMAT <a class="header-anchor" href="#tag-format" aria-label="Permalink to &quot;TAG FORMAT&quot;">​</a></h2><p>A tag signature file, to be fed to this command&#39;s standard input, has a very simple fixed format: four lines of</p><blockquote><pre><code>object &lt;hash&gt;
type &lt;typename&gt;
tag &lt;tagname&gt;
tagger &lt;tagger&gt;
</code></pre></blockquote><p>followed by some <em>optional</em> free-form message (some tags created by older Git may not have <strong>tagger</strong> line). The message, when it exists, is separated by a blank line from the header. The message part may contain a signature that Git itself doesn&#39;t care about, but that can be verified with gpg.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,21);function c(t,d,h,m,p,u){return e(),o("div",null,[s("h1",g,i(t.$params.man),1),l])}const f=a(r,[["render",c]]);export{b as __pageData,f as default};
